<?php $media=app('country_media')->forCountry(country()->country); ?>
<section class="market-page-hero compact-market-hero"><img src="<?= e($media['hero_url']) ?>" alt="<?= e($media['alt']) ?>" loading="eager"><div class="market-page-overlay"><p class="eyebrow">Company information</p><h1>Licence information</h1><p>Only actual administrator-uploaded documents are displayed here. We do not recreate or fabricate regulatory documents.</p></div></section><section class="legal-shell"><?php if(!$license||empty($license['document_path'])): ?><div class="empty-state compliance-empty"><h2>No licence document is currently published.</h2><p>When an applicable document is available, it will appear here with its recorded regulator, number and validity information.</p></div><?php else: ?><div class="license-grid"><article class="detail-panel"><p class="section-label">Current document</p><h2><?= e($license['license_name']??'Current licence') ?></h2><dl class="detail-list polished-detail-list"><dt>Regulator</dt><dd><?= e($license['regulator_name']??'—') ?></dd><dt>Number</dt><dd><?= e($license['license_number']??'—') ?></dd><dt>Status</dt><dd><span class="badge"><?= e($license['calculated_status']) ?></span></dd><dt>Issue date</dt><dd><?= e($license['issue_date']??'—') ?></dd><dt>Expiry date</dt><dd><?= e($license['expiry_date']??'—') ?></dd></dl><div class="button-row"><a class="button" target="_blank" href="<?= e(route('license.document',['license'=>$license['id']])) ?>">Open document</a><a class="button button-secondary" href="<?= e(route('license.document',['license'=>$license['id']]).'?download=1') ?>">Download</a></div></article><article class="license-viewer"><?php if(str_starts_with((string)$license['mime_type'],'image/')): ?><img src="<?= e(route('license.document',['license'=>$license['id']])) ?>" alt="<?= e($license['license_name']??'Licence document') ?>"><?php else: ?><iframe title="Licence document" src="<?= e(route('license.document',['license'=>$license['id']])) ?>"></iframe><?php endif;?></article></div><?php endif;?></section>
